results.body:
{
  name: 'aks-nodeos-autoupgrade'
  location: location
  tags: tags
  kind: 'LogAlert'
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    displayName: 'aks-nodeos-autoupgrade'
    description: 'AKS Node OS auto-upgrade detected via ARG events'
    enabled: true
    scopes: [aksCluster.id]
    evaluationFrequency: 'PT30M'
    windowSize: 'PT60M'
    severity: 3
    autoMitigate: true
    criteria: {
      allOf: [
        {
          query: aksNodeOsAutoUpgradeKql
          timeAggregation: 'Count'
          operator: 'GreaterThan'
          threshold: 0
          metricMeasureColumn: ''
          dimensions: [
            {
              name: 'status'
              operator: 'Include'
              values: ['*']
            }
          ]
        }
      ]
    }
    actions: {
      actionGroups: actionGroupId != '' ? [actionGroupId] : []
    }
  }
}

{
  name: 'fleet-approval-pending'
  location: location
  tags: tags
  kind: 'LogAlert'
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    displayName: 'fleet-approval-pending'
    description: 'Fleet manual approval gate is pending approval.'
    enabled: true
    scopes: [resourceGroup().id]
    evaluationFrequency: 'PT30M'
    windowSize: 'PT60M'
    severity: 3
    autoMitigate: true
    criteria: {
      allOf: [
        {
          query: pendingApprovalGateKql
          timeAggregation: 'Count'
          operator: 'GreaterThan'
          threshold: 0
          metricMeasureColumn: ''
          dimensions: []
        }
      ]
    }
    actions: {
      actionGroups: actionGroupId != '' ? [actionGroupId] : []
    }
  }
  dependsOn: [
    autoUpgradeProfile
  ]
}
